16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_member_count")
82	    private Integer householdMemberCount;
83	
84	    @Column(name = "possible_duplicate")
85	    private boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getTitle() {
94	        return this.title;
95	    }
96	
97	    public void setTitle(String title) {
98	        this.title = title;
99	    }
100	
101	    /**
102	     * The owner's salutation: the supplied {@code title} (MR/MRS/MS/DR) followed by a
103	     * single space and the {@code lastName}, or just the {@code lastName} when no title
104	     * was given.
105	     */
106	    @Transient
107	    public String getSalutation() {
108	        if (this.title == null || this.title.isBlank()) {
109	            return getLastName();
110	        }
111	        return this.title + " " + getLastName();
112	    }
113	
114	    public String getAddress() {
115	        return this.address;
116	    }
117	
118	    public void setAddress(String address) {
119	        this.address = address;
120	    }
121	
122	    public String getAddressLine1() {
123	        return this.addressLine1;
124	    }
125	
126	    public void setAddressLine1(String addressLine1) {
127	        this.addressLine1 = addressLine1;
128	    }
129	
130	    public String getAddressLine2() {
131	        return this.addressLine2;
132	    }
133	
134	    public void setAddressLine2(String addressLine2) {
135	        this.addressLine2 = addressLine2;
136	    }
137	
138	    public String getCity() {
139	        return this.city;
140	    }
141	
142	    public void setCity(String city) {
143	        this.city = city;
144	    }
145	
146	    public String getTelephone() {
147	        return this.telephone;
148	    }
149	
150	    public void setTelephone(String telephone) {
151	        this.telephone = telephone;
152	    }
153	
154	    public String getEmail() {
155	        return this.email;
156	    }
157	
158	    public void setEmail(String email) {
159	        this.email = email;
160	    }
161	
162	    public String getPostcode() {
163	        return this.postcode;
164	    }
165	
166	    public void setPostcode(String postcode) {
167	        this.postcode = postcode;
168	    }
169	
170	    public LocalDate getRegistrationDate() {
171	        return this.registrationDate;
172	    }
173	
174	    public void setRegistrationDate(LocalDate registrationDate) {
175	        this.registrationDate = registrationDate;
176	    }
177	
178	    public LocalDate getBirthDate() {
179	        return this.birthDate;
180	    }
181	
182	    public void setBirthDate(LocalDate birthDate) {
183	        this.birthDate = birthDate;
184	    }
185	
186	    /**
187	     * The owner's age band, derived from {@code birthDate} measured against
188	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
189	     * 64, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
190	     * supplied, so the field is absent from the response.
191	     */
192	    @Transient
193	    public String getAgeBand() {
194	        if (this.birthDate == null || this.registrationDate == null) {
195	            return null;
196	        }
197	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
198	        if (years < 18) {
199	            return "MINOR";
200	        }
201	        if (years < 65) {
202	            return "ADULT";
203	        }
204	        return "SENIOR";
205	    }
206	
207	    public String getCustomerCode() {
208	        return this.customerCode;
209	    }
210	
211	    public void setCustomerCode(String customerCode) {
212	        this.customerCode = customerCode;
213	    }
214	
215	    public String getHouseholdId() {
216	        return this.householdId;
217	    }
218	
219	    public void setHouseholdId(String householdId) {
220	        this.householdId = householdId;
221	    }
222	
223	    public Integer getNamesakeCount() {
224	        return this.namesakeCount;
225	    }
226	
227	    public void setNamesakeCount(Integer namesakeCount) {
228	        this.namesakeCount = namesakeCount;
229	    }
230	
231	    public Integer getHouseholdMemberCount() {
232	        return this.householdMemberCount;
233	    }
234	
235	    public void setHouseholdMemberCount(Integer householdMemberCount) {
236	        this.householdMemberCount = householdMemberCount;
237	    }
238	
239	    public boolean isPossibleDuplicate() {
240	        return this.possibleDuplicate;
241	    }
242	
243	    public void setPossibleDuplicate(boolean possibleDuplicate) {
244	        this.possibleDuplicate = possibleDuplicate;
245	    }
246	
247	    public Integer getPossibleDuplicateOf() {
248	        return this.possibleDuplicateOf;
249	    }
250	
251	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
252	        this.possibleDuplicateOf = possibleDuplicateOf;
253	    }
254	
255	    /**
256	     * The owner's membership points, accumulated from four factors: start at 0, add 2
257	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
258	     * household of 3 or more members, and add 3 when the owner's tenure exceeds 365
259	     * days. The tenure points are the only route to 6 or more: because a newly created
260	     * owner has zero tenure, a new owner scores at most 5 points (2 email + 1 namesake
261	     * + 2 household).
262	     */
263	    @Transient
264	    public int getMembershipPoints() {
265	        int points = 0;
266	        if (this.email != null && !this.email.isBlank()) {
267	            points += 2;
268	        }
269	        if (this.namesakeCount != null && this.namesakeCount == 0) {
270	            points += 1;
271	        }
272	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
273	            points += 2;
274	        }
275	        if (getTenureDays() > 365) {
276	            points += 3;
277	        }
278	        return points;
279	    }
280	
281	    /**
282	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
283	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
284	     * created owner scores at most 5 points (tenure being the only route to 6), a new
285	     * owner never exceeds level 3.
286	     */
287	    @Transient
288	    public int getMembershipLevel() {
289	        int points = getMembershipPoints();
290	        if (points <= 1) {
291	            return 1;
292	        }
293	        if (points <= 3) {
294	            return 2;
295	        }
296	        if (points <= 5) {
297	            return 3;
298	        }
299	        return 4;
300	    }
301	
302	    /**
303	     * The owner's tenure in whole days: the span from {@code registrationDate} to today.
304	     * Zero when no registration date is set, and zero for an owner registered today, so
305	     * the tenure point of {@link #getMembershipLevel()} is never earned at creation.
306	     */
307	    @Transient
308	    public long getTenureDays() {
309	        if (this.registrationDate == null) {
310	            return 0;
311	        }
312	        return java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
313	    }
314	
315	    /**
316	     * The owner's canonical region, preferring the postcode over the city.
317	     *
318	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
319	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
320	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
321	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
322	     * backs both the {@code locality} field and the {@code REGION} segment of the
323	     * {@code customerCode}, so the two always agree.
324	     */
325	    @Transient
326	    public String getRegion() {
327	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
328	            int value = Integer.parseInt(this.postcode);
329	            if (value >= 2000 && value <= 2099) {
330	                return "NSW";
331	            }
332	            if (value >= 3000 && value <= 3099) {
333	                return "VIC";
334	            }
335	            if (value >= 4000 && value <= 4099) {
336	                return "QLD";
337	            }
338	        }
339	        if ("Sydney".equals(this.city)) {
340	            return "NSW";
341	        }
342	        if ("Melbourne".equals(this.city)) {
343	            return "VIC";
344	        }
345	        if ("Brisbane".equals(this.city)) {
346	            return "QLD";
347	        }
348	        return "UNKNOWN";
349	    }
350	
351	    /**
352	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
353	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
354	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
355	     */
356	    @Transient
357	    public String getTimezone() {
358	        switch (getRegion()) {
359	            case "NSW":
360	                return "Australia/Sydney";
361	            case "VIC":
362	                return "Australia/Melbourne";
363	            case "QLD":
364	                return "Australia/Brisbane";
365	            default:
366	                return null;
367	        }
368	    }
369	
370	    /**
371	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
372	     * present, otherwise {@code PHONE}.
373	     */
374	    @Transient
375	    public String getContactPreference() {
376	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
377	    }
378	
379	    /**
380	     * The owner's derived duplicate-detection key: the normalized (E.164) telephone,
381	     * the email (or empty when absent) and the {@code householdId} (or empty when
382	     * absent), joined by {@code '|'}. Two owners are duplicates only when their whole
383	     * identity keys are equal.
384	     */
385	    @Transient
386	    public String getIdentityKey() {
387	        String tel = this.telephone == null ? "" : this.telephone;
388	        String mail = this.email == null ? "" : this.email;
389	        String household = this.householdId == null ? "" : this.householdId;
390	        return tel + "|" + mail + "|" + household;
391	    }
392	
393	    protected Set<Pet> getPetsInternal() {
394	        if (this.pets == null) {
395	            this.pets = new HashSet<>();
396	        }
397	        return this.pets;
398	    }
399	
400	    protected void setPetsInternal(Set<Pet> pets) {
401	        this.pets = pets;
402	    }
403	
404	    public List<Pet> getPets() {
405	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
406	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
407	        return Collections.unmodifiableList(sortedPets);
408	    }
409	
410	    public void setPets(List<Pet> pets) {
411	        this.pets = new HashSet<>(pets);
412	    }
413	
414	    public void addPet(Pet pet) {
415	        getPetsInternal().add(pet);
416	        pet.setOwner(this);
417	    }
418	
419	    /**
420	     * Return the Pet with the given name, or null if none found for this Owner.
421	     *
422	     * @param name to test
423	     * @return true if pet name is already in use
424	     */
425	    public Pet getPet(String name) {
426	        return getPet(name, false);
427	    }
428	
429	    /**
430	     * Return the Pet with the given name, or null if none found for this Owner.
431	     *
432	     * @param name to test
433	     * @return true if pet name is already in use
434	     */
435	    public Pet getPet(String name, boolean ignoreNew) {
436	        name = name.toLowerCase();
437	        for (Pet pet : getPetsInternal()) {
438	            if (!ignoreNew || !pet.isNew()) {
439	                String compName = pet.getName();
440	                compName = compName.toLowerCase();
441	                if (compName.equals(name)) {
442	                    return pet;
443	                }
444	            }
445	        }
446	        return null;
447	    }
448	
449	    public Pet getPet(Integer petId) {
450	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
451	    }
452	
453	    @Override
454	    public String toString() {
455	        return new ToStringCreator(this)
456	
457	            .append("id", this.getId())
458	            .append("new", this.isNew())
459	            .append("lastName", this.getLastName())
460	            .append("firstName", this.getFirstName())
461	            .append("address", this.address)
462	            .append("city", this.city)
463	            .append("telephone", this.telephone)
464	            .toString();
465	    }
466	}
